"""Post-execution pipeline steps for CompoundExecutor.

Extracted from the monolithic ``execute_task`` method. Each function
performs one non-blocking pipeline step, returning any vault paths
created. All steps are wrapped in try/except to be non-blocking.
"""

from __future__ import annotations

import asyncio
import json
import logging
import time
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from .executor import CompoundExecutor, ExecutionResult

logger = logging.getLogger(__name__)

_background_tasks: set[asyncio.Task[Any]] = set()


def run_anomaly_detection(
    executor: CompoundExecutor,
    result: ExecutionResult,
    skill_name: str,
    task_description: str,
    project: str,
) -> list[str]:
    """Step 5: Detect anomalies and log critical inflection points."""
    paths: list[str] = []
    try:
        from cohezion.compound.inflection_detector import Severity

        anomaly = executor.inflection_detector.detect_anomaly(result)
        result.metrics["anomaly_severity"] = anomaly.severity.value
        result.metrics["anomaly_score"] = anomaly.score
        logger.debug(
            "Anomaly detection: severity=%s, score=%.2f",
            anomaly.severity.value,
            anomaly.score,
        )
        if anomaly.severity == Severity.CRITICAL:
            logger.warning("Critical inflection point: %d issues", len(anomaly.issues))
            try:
                dp = executor.log_inflection_point(
                    title=f"Critical anomaly in {skill_name}",
                    context=f"Task: {task_description}\nIssues: {'; '.join(anomaly.issues)}",
                    decision="Re-execution recommended",
                    rationale=(
                        f"Quality score {anomaly.score:.2f}, "
                        f"{anomaly.recommendations[0] if anomaly.recommendations else 'Investigate issues'}"
                    ),
                    project=project,
                )
                if dp:
                    paths.append(dp)
            except Exception as e:
                logger.debug("Failed to log inflection point: %s", e)
    except Exception as e:
        logger.debug("Anomaly detection failed (non-blocking): %s", e, exc_info=True)
    return paths


def run_alignment_analysis(
    executor: CompoundExecutor,
    result: ExecutionResult,
    parsed_request: Any,
    operation_type: str,
    project: str,
) -> list[str]:
    """Step 5.5: Analyze request-execution alignment."""
    paths: list[str] = []
    if not (executor._enable_alignment_analysis and executor.alignment_analyzer and parsed_request):
        return paths
    try:
        from cohezion.compound.inflection_detector import AnomalyDetection, Severity

        anomaly_analysis = None
        if "anomaly_severity" in result.metrics:
            severity_enum = Severity(result.metrics.get("anomaly_severity", "info"))
            anomaly_analysis = AnomalyDetection(
                severity=severity_enum,
                score=result.metrics.get("anomaly_score", 0.0),
                issues=result.metrics.get("anomaly_issues", []),
                recommendations=result.metrics.get("anomaly_recommendations", []),
                should_reexecute=False,
            )
        alignment = executor.alignment_analyzer.analyze_alignment(
            parsed_request, result, operation_type, anomaly_analysis
        )
        if alignment.misalignment_score > 0.3:
            vault_path = executor.alignment_analyzer.log_alignment_to_vault(
                parsed_request, alignment, project
            )
            if vault_path:
                paths.append(vault_path)
        result.metrics["alignment"] = {
            "misalignment_score": alignment.misalignment_score,
            "intent_match": alignment.intent_match_score,
            "constraint_satisfaction": alignment.constraint_satisfaction,
            "criteria_satisfaction": alignment.criteria_satisfaction,
            "violations_count": len(alignment.violations),
            "failures_count": len(alignment.failures),
            "issues_count": len(alignment.issues),
            "should_retry": alignment.should_retry,
        }
    except Exception as e:
        logger.debug("Alignment analysis failed (non-blocking): %s", e, exc_info=True)
    return paths


def run_pattern_extraction(
    executor: CompoundExecutor,
    experiment_path: str,
    skill_name: str,
    operation_type: str,
    task_description: str,
    metrics: dict[str, Any],
) -> list[str]:
    """Step 6: Extract patterns from successful execution."""
    paths: list[str] = []
    try:
        pattern_path = executor.logger.extract_execution_pattern(
            source_path=experiment_path,
            pattern_name=f"{skill_name}_{operation_type}_success",
            description=(
                f"Successful execution pattern for {skill_name} "
                f"operation: {operation_type}. Task: {task_description[:100]}"
            ),
            code_example=f"Result metrics: {json.dumps(metrics, indent=2)}",
            domain="compound-engineering",
        )
        if pattern_path:
            paths.append(pattern_path)
    except Exception as e:
        logger.warning("Failed to extract pattern: %s", e, exc_info=True)
    return paths


def run_retrospection(
    executor: CompoundExecutor,
    result: ExecutionResult,
    skill_name: str,
) -> tuple[bool, dict[str, Any] | None]:
    """Step 7.3: Run retrospection analysis (gates skill refinement).

    Returns:
        (should_refine, retrospection_context)
    """
    if not executor._retrospection_engine:
        return True, None
    try:
        ctx = executor._retrospection_engine.analyze_execution_result(result, skill_name)
        should_refine = ctx.get("should_refine", True)
        if ctx.get("insights"):
            result.metrics["retrospection_insights"] = ctx["insights"]
        logger.debug(
            "Retrospection: should_refine=%s, compound=%.3f",
            should_refine,
            ctx.get("compound_score", 0.0),
        )
        return should_refine, ctx
    except Exception as e:
        logger.debug("Retrospection failed (non-blocking): %s", e, exc_info=True)
        return True, None


def run_skill_refinement(
    executor: CompoundExecutor,
    result: ExecutionResult,
    skill_name: str,
    operation_type: str,
    decision_paths: list[str],
) -> list[str]:
    """Step 7: Refine skills based on execution results."""
    paths: list[str] = []
    if not executor.skill_refiner:
        return paths
    try:
        exec_result = {
            "success": result.success,
            "output": result.output,
            "metrics": result.metrics,
            "duration_seconds": result.duration_seconds,
            "token_metrics": result.token_metrics,
        }
        refined_path = executor.skill_refiner.refine(
            skill_name=skill_name,
            operation_type=operation_type,
            execution_result=exec_result,
            patterns_extracted=decision_paths,
        )
        if refined_path:
            logger.info("Skill refined: %s", refined_path)
            paths.append(refined_path)
    except Exception as e:
        logger.debug("Skill refinement failed (non-blocking): %s", e, exc_info=True)
    return paths


def run_degradation_check(
    executor: CompoundExecutor,
    result: ExecutionResult,
    task_description: str,
    project: str,
) -> list[str]:
    """Step 7.5: Check for degradation and manage HIHO band."""
    paths: list[str] = []
    coherence_val = result.metrics.get("coherence", 0.5)

    if 0.4 <= coherence_val <= 0.6 and executor._degradation_mode:
        logger.info("Cohesion returned to HIHO band (%.2f), exiting degradation mode", coherence_val)
        executor._degradation_mode = False

    if not executor._degradation_detector:
        return paths
    try:
        degradation_metrics = {
            "combined_hit_rate": 0.0,
            "tokens_per_second": 0.0,
            "mean_coherence": coherence_val,
            "elapsed_seconds": result.duration_seconds,
            "success_rate": 1.0 if result.success else 0.0,
        }
        if result.token_metrics:
            degradation_metrics["combined_hit_rate"] = result.token_metrics.get(
                "cache_hit_rate", result.token_metrics.get("combined_hit_rate", 0.0)
            )
            degradation_metrics["tokens_per_second"] = result.token_metrics.get("tokens_per_second", 0.0)
        alerts = executor._degradation_detector.check_degradation(degradation_metrics)
        if alerts:
            result.metrics["degradation_alerts"] = len(alerts)
            for alert in alerts:
                logger.warning("Degradation alert [%s]: %s", alert.severity.value, alert.message)
            critical_alerts = [a for a in alerts if a.severity.value == "CRITICAL"]
            if critical_alerts:
                executor._degradation_mode = True
                result.metrics["execution_degraded"] = True
            for alert in critical_alerts:
                try:
                    dp = executor.log_inflection_point(
                        title=f"Degradation: {alert.metric}",
                        context=f"Task: {task_description}\n{alert.message}",
                        decision="Investigate degradation",
                        rationale=(
                            f"Current: {alert.current_value:.3f}, "
                            f"Baseline: {alert.baseline_value:.3f}, "
                            f"Threshold: {alert.threshold:.3f}"
                        ),
                        project=project,
                    )
                    if dp:
                        paths.append(dp)
                except Exception as e:
                    logger.debug("Failed to log degradation alert: %s", e)
    except Exception as e:
        logger.debug("Degradation detection failed (non-blocking): %s", e)
    return paths


def run_quality_recording(executor: CompoundExecutor, result: ExecutionResult) -> None:
    """Step 7.7: Record model quality."""
    if not executor._model_quality_classifier:
        return
    try:
        model_name = "unknown"
        tokens_used = 0
        if result.token_metrics:
            model_name = result.token_metrics.get("model", "unknown")
            tokens_used = result.token_metrics.get("tokens_used", 0)
        executor._model_quality_classifier.add_execution(
            model=model_name,
            coherence=result.metrics.get("coherence", 0.5),
            success=result.success,
            tokens_used=tokens_used,
            duration=result.duration_seconds,
        )
    except Exception as e:
        logger.debug("Model quality recording failed (non-blocking): %s", e)


def run_metrics_recording(executor: CompoundExecutor, result: ExecutionResult, skill_name: str) -> None:
    """Step 8: Record execution metrics."""
    if not executor._metrics_collector:
        return
    try:
        tokens_used = 0
        model_used = ""
        if result.token_metrics:
            tokens_used = result.token_metrics.get("tokens_used", 0)
            model_used = result.token_metrics.get("model", "")
        executor._metrics_collector.record_execution(
            skill_name=skill_name,
            success=result.success,
            tokens_used=tokens_used,
            duration_ms=result.duration_seconds * 1000,
            model_used=model_used,
        )
    except Exception as e:
        logger.debug("Metrics recording failed (non-blocking): %s", e)


def run_journey_tracking(
    executor: CompoundExecutor,
    result: ExecutionResult,
    task_description: str,
    operation_type: str,
) -> bool:
    """Step 9: Track journey. Returns True if a point was tracked."""
    if not executor._journey_tracker:
        return False
    try:
        point = executor._journey_tracker.track_execution(result, task_description, operation_type)
        if point and point.metadata:
            result.metrics["phi_score"] = point.metadata.get("phi_score", 0.0)
        if executor._journey_persistence and point:
            try:
                point_data = {
                    "coherence": point.coherence,
                    "efficiency": point.efficiency,
                    "operation_type": point.operation_type,
                    "task_description": point.task_description[:200],
                    "timestamp": point.timestamp,
                }
                if point.metadata:
                    point_data["metadata"] = point.metadata
                exec_id = f"exec_{int(time.time())}"
                try:
                    asyncio.get_running_loop()
                    task = asyncio.ensure_future(
                        executor._journey_persistence.save_trajectory_point(exec_id, point_data)
                    )
                    _background_tasks.add(task)
                    task.add_done_callback(_background_tasks.discard)
                except RuntimeError:
                    asyncio.run(executor._journey_persistence.save_trajectory_point(exec_id, point_data))
            except Exception as e:
                logger.debug("Journey persistence failed (non-blocking): %s", e)
        return True
    except Exception as e:
        logger.debug("Journey tracking failed (non-blocking): %s", e)
        return False


def run_universe_bridge(
    executor: CompoundExecutor,
    result: ExecutionResult,
    universe_journey_id: str | None,
    operation_type: str,
    journey_tracked: bool,
) -> None:
    """Steps 9.5 and 10: Update universe bridge with trajectory and completion."""
    if not executor._universe_bridge or not universe_journey_id:
        return
    # Step 9.5: Add trajectory point
    if journey_tracked and executor._journey_tracker:
        try:
            last_point = executor._journey_tracker.get_last_point()
            if last_point:
                executor._universe_bridge.add_point(
                    universe_journey_id,
                    last_point,
                    step_number=executor._journey_tracker.get_recent_point_count(),
                    action=operation_type,
                )
        except Exception as e:
            logger.debug("Universe bridge point failed (non-blocking): %s", e)
    # Step 10: Complete journey
    try:
        phi = result.metrics.get("phi_score", 0.0)
        executor._universe_bridge.complete_journey(
            universe_journey_id,
            success=result.success,
            phi_score=phi,
            output=result.output[:500],
        )
    except Exception as e:
        logger.debug("Universe bridge completion failed (non-blocking): %s", e)

